import BaseFoundation, { DefaultAdapter } from '../base/foundation';
import { isNumber } from 'lodash';
import { strings } from '../notification/constants';


export type NoticePosition = 'top' | 'bottom' | 'topLeft' | 'topRight' | 'bottomLeft' | 'bottomRight';
export type NoticeType = 'warning' | 'success' | 'info' | 'error' | 'default';
export type NoticeTheme = 'light' | 'normal';


export interface NoticeProps {
    duration?: number;
    id?: string;
    title?: any;
    content?: any;
    position?: NoticePosition;
    type?: NoticeType;
    onClick?: (e: any) => void;
    onClose?: () => void;
    onCloseClick?: (id: string) => void;
    showClose?: boolean;
    close?: (id: string) => void;
    zIndex?: number;
    icon?: any;
    getPopupContainer?: () => HTMLElement;
    theme?: NoticeTheme;
    onHookClose?: () => void;
    direction?: typeof strings.directions[number];
    className?: string;
    style?: any
}

export interface NoticeState{
    visible: boolean
}

export interface NoticeInstance extends NoticeProps{
    motion?: boolean
}

export interface NoticeAdapter extends DefaultAdapter<NoticeProps, NoticeState>{
    notifyWrapperToRemove: (id: string) => void;
    notifyClose: () => void
}



export default class NotificationFoundation extends BaseFoundation<NoticeAdapter> {


    _timer: ReturnType<typeof setTimeout> | null = null;

    _id: string | null = null; // cache id

    constructor(adapter: NoticeAdapter) {
        super({ ...NotificationFoundation.defaultAdapter, ...adapter });
    }


    init() {
        this._startCloseTimer();
        this._id = this.getProp('id');
    }

    destroy() {
        this._clearCloseTimer();
    }

    _startCloseTimer() {
        // unit: s
        const duration = this.getProp('duration');
        if (duration && isNumber(duration)) {
            this._timer = setTimeout(() => {
                this.close(); // call parent to remove itself
            }, duration * 1000);
        }
    }

    close(e?: any) {
        if (e) {
            e.stopPropagation();
        }
        this._adapter.notifyWrapperToRemove(this._id);
        this._adapter.notifyClose();
    }

    _clearCloseTimer() {
        if (this._timer) {
            clearTimeout(this._timer);
            this._timer = null;
        }
    }

    restartCloseTimer() {
        this._clearCloseTimer();
        this._startCloseTimer();
    }
}

import BaseFoundation, { DefaultAdapter } from '../base/foundation';
import { NoticeInstance, NoticePosition, NoticeProps } from '../notification/notificationFoundation';
import { strings } from './constants';


export interface NotificationListProps {

}

export interface NotificationListState {
    notices: NoticeInstance[];
    removedItems: NoticeInstance[];
    updatedItems: NoticeInstance[]
}

export interface NotificationListAdapter extends DefaultAdapter<NotificationListProps, NotificationListState> {
    updateNotices: (notices: NoticeInstance[], removedItems?: NoticeInstance[], updatedItems?: NoticeInstance[]) => void;
    getNotices: () => NoticeInstance[]
}


export interface ConfigProps {
    top?: number | string;
    bottom?: number | string;
    left?: number | string;
    right?: number | string;
    duration?: number;
    position?: NoticePosition;
    zIndex?: number;
    direction?: typeof strings.directions[number]
}


export default class NotificationListFoundation extends BaseFoundation<NotificationListAdapter> {

    addNotice(opts: NoticeProps) {
        // let notices = this._adapter.getNotices();
        const notices = this._adapter.getNotices();

        // opts = { ...opts, id };
        // if (opts.duration) {
        //     setTimeout(() => {
        //         this.removeNotice(opts.id);
        //     }, opts.duration * 1000);
        // }
        this._adapter.updateNotices([opts, ...notices]);
        // return id;
    }

    has(id: string) {
        return this._adapter.getNotices().some(notice=>notice.id===id);
    }

    update(id: string, noticeOpts: NoticeProps) {
        let notices = this._adapter.getNotices();
        notices = notices.map((notice) => notice.id === id ? { ...notice, ...noticeOpts }: notice);
        const updatedItems = notices.filter(notice=>notice.id === id);
        this._adapter.updateNotices(notices, [], updatedItems);
    }

    removeNotice(id: string) {
        let notices = this._adapter.getNotices();
        // let notices = this._adapter.getNotices();
        const removedItems: NoticeInstance[] = [];
        notices = notices.filter(notice => {
            if (notice.id === id) {
                removedItems.push(notice);
                return false;
            }
            return true;
        });
        this._adapter.updateNotices(notices, removedItems); // This must be updated at the same time https://github.com/facebook/react/issues/12312
    }

    destroyAll() {
        const notices = this._adapter.getNotices();
        if (notices.length > 0) {
            this._adapter.updateNotices([], notices);
        }
    }

}

