import BaseFoundation, { DefaultAdapter } from '../base/foundation';
import warning from '../utils/warning';

export interface RadioAdapter extends DefaultAdapter {
    setHover: (hover: boolean) => void;
    setChecked: (checked: boolean) => void;
    setAddonId: () => void;
    setExtraId: () => void;
    setFocusVisible: (focusVisible: boolean) => void
}
export default class RadioFoundation extends BaseFoundation<RadioAdapter> {
    init() {
        const { children, extra, extraId, addonId } = this._adapter.getProps();
        if (children && !addonId) {
            this._adapter.setAddonId();
        }
        if (extra && !extraId) {
            this._adapter.setExtraId();
        }
    }
    setHover(hover: boolean) {
        this._adapter.setHover(hover);
    }

    setChecked(checked: boolean) {
        this._adapter.setChecked(checked);
    }

    handleFocusVisible = (event: any) => {
        const { target } = event;
        try {
            if (target.matches(':focus-visible')) {
                this._adapter.setFocusVisible(true);
            }
        } catch (error) {
            warning(true, 'Warning: [Semi Radio] The current browser does not support the focus-visible');
        }
    }

    handleBlur = () => {
        this._adapter.setFocusVisible(false);
    }
}

import BaseFoundation, { DefaultAdapter } from '../base/foundation';
import { RadioChangeEvent } from './radioInnerFoundation';

export interface RadioGroupAdapter extends DefaultAdapter {
    isInProps?: (name: string) => boolean;
    notifyChange?: (e: RadioChangeEvent) => void;
    setValue?: (value: any) => void
}

export default class RadioGroupFoundation extends BaseFoundation<RadioGroupAdapter> {
    constructor(adapter: RadioGroupAdapter) {
        super({ ...adapter });
    }

    init() {
        const displayValue = this._getDisplayValue();
        this._setValue(displayValue);
    }

    _getDisplayValue() {
        const { value, defaultValue } = this.getProps();
        let displayValue;

        if ('value' in this.getProps()) {
            displayValue = value;
        } else if ('defaultValue' in this.getProps()) {
            displayValue = defaultValue;
        }
        return displayValue;
    }

    handleChange(evt: any) {
        const mode = this.getProp('mode');
        const lastValue = this.getState('value');
        const { checked, value } = evt.target;
        const isControlledComponent = this._adapter.isInProps('value');

        const cbValue = {
            ...evt,
            target: {
                ...evt.target,
                value,
            }
        };

        if (mode === 'advanced' && !checked) {
            cbValue.target.value = undefined;
        }

        if (!isControlledComponent) {
            if (mode === 'advanced' && !checked) {
                this._setValue(undefined);
            } else {
                this._setValue(value);
            }
        }

        if (mode === 'advanced' || lastValue !== value) {
            this._adapter.notifyChange(cbValue);
        }
    }

    // call when prop.value change
    handlePropValueChange(propValue: any) {
        this._setValue(propValue);
    }

    _setValue(value: any) {
        this._adapter.setValue(value);
    }

    destroy() {}
}

import BaseFoundation, { DefaultAdapter } from '../base/foundation';

export interface RadioChangeEvent {
    target: {
        [x: string]: any;
        checked: boolean;
        value: any
    };
    stopPropagation: () => void;
    preventDefault: () => void
}

export interface RadioInnerAdapter extends DefaultAdapter {
    notifyChange?: (e: RadioChangeEvent) => void;
    setNativeControlChecked?: (checked: boolean) => void
}

export default class RadioInnerFoundation extends BaseFoundation<RadioInnerAdapter> {
    constructor(adapter: RadioInnerAdapter) {
        super({ ...adapter });
    }

    init() {
        const checked = this._adapter.getProp('checked');
        const defaultChecked = this._adapter.getProp('defaultChecked');
        this.setChecked(checked || defaultChecked);
    }

    setChecked(checked: boolean) {
        this._adapter.setNativeControlChecked(checked);
    }

    getChecked() {
        return this._adapter.getProp('checked');
    }

    handleChange(e: any) {
        const isControlledMode = 'checked' in this.getProps();
        const { checked } = e.target;

        const stopPropagation = () => {
            e.stopPropagation();
        };
        const preventDefault = () => {
            e.preventDefault();
        };
        const cbValue = {
            target: {
                ...this.getProps(),
                checked,
            },
            stopPropagation,
            preventDefault
        };
        if (isControlledMode) {
            this._adapter.notifyChange(cbValue);
        } else {
            this.setChecked(checked);
            this._adapter.notifyChange(cbValue);
        }
    }

    destroy() {}
}

$module: #{$prefix}-radio;
$inner-width: $width-icon-medium;

.#{$prefix}-rtl,
.#{$prefix}-portal-rtl {
    .#{$module} {
        direction: rtl;

        input[type="checkbox"],
        input[type="radio"] {
            left: auto;
            right: 0;
        }

        &-buttonRadioGroup {
            &:not(:last-child) {
                padding-left: $spacing-radio_buttonRadioGroup-paddingRight;
            }
        }
    }

    .#{$module}Group {
        direction: rtl;
    }
}

